mapper.select:
SELECT target_kind,target_id,visited_at FROM recent_visit WHERE owner_id=#{owner}
AND target_kind=#{kind}

  AND (visited_at < #{cursorTime}
    OR (visited_at=#{cursorTime} AND target_kind > #{cursorKind})
    OR (visited_at=#{cursorTime} AND target_kind=#{cursorKind} AND target_id > #{cursorId}))

ORDER BY visited_at DESC,target_kind ASC,target_id ASC LIMIT #{limit}

choose.when:
SELECT s.title,r.question_mode AS subtype,s.status FROM review_repractice r JOIN training_session s
  ON s.owner_id=r.owner_id AND s.id=r.session_id
WHERE r.owner_id=#{owner} AND r.id=#{id}
